args.command:
perl << 'PERL'
# read pgm and dump vertical profile averaged over x range
sub read_pgm {
  my ($path) = @_;
  open my $fh, '<:raw', $path or die $!;
  my $magic = <$fh>;
  my $line = <$fh>;
  while ($line =~ /^#/) { $line = <$fh>; }
  my ($w,$h) = split ' ', $line;
  my $max = <$fh>;
  # after max line, there is single whitespace? <$fh> consumed newline, data starts
  my $data;
  my $len = $w*$h;
  my $read = read($fh, $data, $len);
  die "short $read vs $len" unless $read==$len;
  close $fh;
  return ($w,$h,$data);
}
my ($w,$h,$d006) = read_pgm('/tmp/s006.pgm');
my ($w2,$h2,$d013) = read_pgm('/tmp/s013.pgm');
print "w=$w h=$h\n";
# choose x range 300-340
my $x0=300; my $x1=340;
for my $y (0..$h-1) {
  my $sum006=0; my $sum013=0; my $cnt=0;
  for my $x ($x0..$x1-1) {
    my $idx = $y*$w+$x;
    $sum006 += ord(substr($d006,$idx,1));
    $sum013 += ord(substr($d013,$idx,1));
    $cnt++;
  }
  my $m006=$sum006/$cnt; my $m013=$sum013/$cnt;
  # print every 5 rows to see
  if ($y%5==0) { printf "%3d %6.1f %6.1f diff %6.1f\n", $y,$m006,$m013,$m013-$m006; }
}
PERL

